HELP = '''
import datetime, re, json
HOL = ['2026-10-26','2026-11-11','2026-11-26','2026-12-25','2027-01-01']
DAYS = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']
MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December']
TD = datetime.timedelta
def parse_now(s):
    s = str(s or '').strip().replace(' ', 'T')
    try:
        if len(s) >= 16:
            return datetime.datetime.strptime(s[:16], '%Y-%m-%dT%H:%M')
        return datetime.datetime.strptime(s[:10] + 'T12:00', '%Y-%m-%dT%H:%M')
    except Exception:
        return datetime.datetime(2026, 10, 14, 11, 0)
def is_bd(d):
    return d.weekday() < 5 and d.isoformat() not in HOL
def add_bd(d, n):
    c = 0
    while c < n:
        d = d + TD(days=1)
        if is_bd(d):
            c += 1
    return d
def sp(d):
    return DAYS[d.weekday()] + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1] + ' ' + str(d.year)
def short(d):
    return DAYS[d.weekday()][:3] + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1][:3]
def resolve_day(text, today):
    t = str(text or '').lower().strip()
    if not t or t == 'none':
        return None
    m = re.search(r'(\\d{4})-(\\d{2})-(\\d{2})', t)
    if m:
        try:
            return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
        except Exception:
            return None
    if 'day after tomorrow' in t:
        return today + TD(days=2)
    if 'tomorrow' in t:
        return today + TD(days=1)
    if 'today' in t or 'tonight' in t:
        return today
    monday = today - TD(days=today.weekday())
    for i in range(7):
        nm = DAYS[i].lower()
        if re.search(r'\\b(' + nm + '|' + nm[:3] + ')\\\\b', t):
            if 'next' in t:
                return monday + TD(days=7 + i)
            if 'this' in t:
                return monday + TD(days=i)
            d = monday + TD(days=i)
            if d < today:
                d = d + TD(days=7)
            return d
    for i in range(12):
        mn = MONTHS[i].lower()
        if mn in t or re.search(r'\\b' + mn[:3] + '\\\\b', t):
            mm = re.search(r'\\b(\\d{1,2})\\b', t)
            if mm:
                try:
                    return datetime.date(today.year, i + 1, int(mm.group(1)))
                except Exception:
                    return None
    return None
'''

