                if i > 0:
                    k += 1
                    tag = tag + 'business day number ' + str(k) + ' after today'
                else:
                    tag = tag + 'business day'
            else:
                if d.weekday() >= 5:
                    tag = tag + 'NOT a business day (weekend)'
                else:
                    tag = tag + 'NOT a business day (bank holiday)'
            if d == deadline:
                tag = tag + ' <== DEADLINE (latest allowed promise date)'
            elif d > deadline:
                tag = tag + ' (AFTER the deadline, not allowed)'
            lines.append(short(d) + ' = ' + d.isoformat() + ': ' + tag)
        w1 = []
        w2 = []
        for i in range(7):
            w1.append(short(monday + TD(days=i)))
            w2.append(short(monday + TD(days=7 + i)))
        vars['calendar_text'] = '\\n'.join(lines) + '\\nTHIS calendar week: ' + ', '.join(w1) + '\\nNEXT calendar week: ' + ', '.join(w2)
        vars['product_id'] = str(p.get('product_id'))
        vars['product_words'] = pname
        vars['past_due'] = amt
        vars['floor'] = flo
        vars['days_late_n'] = str(days)
        vars['deadline_iso'] = deadline.isoformat()
        vars['deadline_spoken'] = sp(deadline)
        vars['attempt1_date_spoken'] = sp(a1)
        vars['attempt1_date_iso'] = a1.isoformat()
        vars['band'] = 'early' if early else 'late'
        if early:
            att = 'ONLY ONE persuasion attempt is allowed (early band). There is no attempt 2.'
            a2 = 'There is no attempt 2 in this band: after attempt 1 is refused, stop.'
        else:
            att = 'TWO persuasion attempts are allowed (late band).'
            a2 = 'Attempt 2: propose the floor amount ' + flo + ' on the deadline ' + sp(deadline) + ' (' + deadline.isoformat() + ').'
        vars['attempts_text'] = att
        vars['attempt2_text'] = a2
        vars['deal_facts'] = ('FACTS: Product: ' + pname + ' (product_id ' + str(p.get('product_id')) + '). Full past-due amount: ' + amt + '. Days late: ' + str(days) + ' (' + ('early' if early else 'late') + ' band). Floor (' + floor_name + '): ' + flo + '. Deadline: ' + sp(deadline) + ' (' + deadline.isoformat() + '). ' + att)
        dl = ' days late.' if days != 1 else ' day late.'
        vars['deal_intro'] = 'Thank you, you are verified. I am calling from the collections team about a late payment on your ' + pname + '. The past-due amount is ' + amt + ' and it is ' + str(days) + dl + ' Can you make this payment today?'
        vars['deal_state'] = 'ready'
except Exception:
    vars['deal_state'] = 'none'
'''


def set_code(outcome, reason, farewell=None, dynamic=None):
    c = "vars['outcome'] = '%s'\nvars['reason'] = '%s'\n" % (outcome, reason)
    if dynamic:
        c += dynamic
    else:
        c += "vars['farewell'] = %r\n" % farewell
    return c


# ---------------------------------------------------------------- builders
def eq(var, *vals):
    return {"logic": "or", "conditions": [{"variable": var, "operator": "equals", "operand": v} for v in vals]}


def truthy(var):
    return eq(var, "true", "True")


def tr(target, desc, cond=None):
    return {"target_node": target, "description": desc, "condition": cond or {"operator": "always"}}


def tool_t(target, desc):
    return {"target_node": target, "description": desc, "is_tool_call": True,
            "condition": {"operator": "matches_intent", "description": desc}}


def api_fn(name, path, props, required, desc=None, retries=0, mapping=None, pre=None, post=None, bake_only=False):
    body_props = {"customer_id": {"type": "string", "default": "{{customer_id}}"}}
    body_props.update(props)
    tool = {
        "type": "function",
        "config": {"timeoutMs": 12000, "maxRetries": retries},
        "function": {
            "name": name,
            "handler": "__function__:api_call",
            "parameters": {"type": "object", "properties": {
                "url": {"type": "string", "default": BASE + path},
                "method": {"type": "string", "default": "POST"},
                "headers": HDR,
                "body": {"type": "object", "required": required, "properties": body_props},
            }},
        },
    }
    if desc:
        tool["function"]["description"] = desc
    if mapping:
        tool["response_mapping"] = mapping
    if pre:
        tool["pre_process_code"] = pre
    if post:
        tool["post_process_code"] = post
    return tool


def code_node(name, code, transitions, default):
    return {
        "name": name, "node_type": "code", "passthrough": True,
        "passthrough_default_transition": default,
        "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
        "pre_actions": [{"type": "function", "function": {
            "name": "code_exec", "handler": "__function__:code_exec",
            "parameters": {"type": "object", "properties": {
                "code": {"type": "string", "default": code},
                "timeout_ms": {"type": "number", "default": 10000}}}}}],
        "transitions": transitions,
    }


def api_node(name, fn, mapping, transitions, default):
    return {
        "name": name, "node_type": "api_request", "passthrough": True,
        "passthrough_default_transition": default,
        "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
        "pre_actions": [fn], "response_mapping": mapping, "transitions": transitions,
    }


def extr(name, desc, typ="string", enum=None, pattern=None):
    e = {"name": name, "type": typ, "description": desc, "min_confidence": 0.7}
    if enum:
        e["enum_values"] = enum
    if pattern:
        e["validation_pattern"] = pattern
    return e


